            };

            // [46] BB\script\output\_sce04_c302_0010_eng#25
            entryTranslators[@"BB\script\output\_sce04_c302_0010_eng#25"] = (s) => {
                R(ref s, "We've wasted enough time!", "Nous avons perdu assez de temps !");
                R(ref s, "It's clear to me <E049><E003 8><E025 2>that any further discussion of this case will\r\nbe fruitless.", "Il m'apparaît clairement <E049><E003 8><E025 2>que tout débat prolongé sur cette affaire sera\r\ninfructueux.");
                R(ref s, "Barok van Zieks, <E049><E003 8><E025 2>I would like to think that however\r\nmisguided...", "Drake Van Peers, <E049><E003 8><E025 2>j'ose croire que, si fourvoyé fussiez-vous...");
                R(ref s, "...you acted out of a sense of justice nonetheless.<E049><E003 12>\r\n<E025 3>Though it pains me to have reached this conclusion...", "... vous avez néanmoins agi selon votre sens de la justice.<E049><E003 12>\r\n<E025 3>Bien qu'il me soit douloureux d'en arriver là...");
                R(ref s, "Wait, My Lord!", "Attendez, Votre Honneur !");
                R(ref s, "In accordance with the findings of this court, <E049><E003 6><E025 3>I hereby\r\npronounce the defendant, <E049><E003 6><E025 3>Barok van Zieks...", "Conformément aux conclusions de ce tribunal, <E049><E003 6><E025 3>je déclare\r\npar la présente l'accusé, <E049><E003 6><E025 3>Drake Van Peers...");
                R(ref s, "That concludes business.<E049><E003 10>\r\n<E025 2>Court is adjourned!", "La séance est levée.<E049><E003 10>\r\n<E025 2>L'audience est terminée !");
                return s;
            };

            // [47] BB\script\output\_sce04_c302_0020_eng#2
            entryTranslators[@"BB\script\output\_sce04_c302_0020_eng#2"] = (s) => {
                R(ref s, "There's no possible way you could have moved Inspector\r\nGregson's body, <E049><E003 6>you say?", "Il vous était absolument impossible de déplacer le corps de l'inspecteur\r\nGregson, <E049><E003 6>dites-vous ?");
                R(ref s, "I would say <E006>the opposite<E005> is true.", "Je dirais bien plutôt que <E006>c'est l'inverse<E005>.");
                R(ref s, "And what's that supposed to mean?", "Et qu'est-ce que cela est censé signifier ?");
                R(ref s, "Far from being impossible for you to do...", "Loin de vous être impossible...");
                R(ref s, "...the transporting of Inspector Gregson's body back to\r\nBritain is something ONLY you could do!", "... le transport du corps de l'inspecteur Gregson en\r\nGrande-Bretagne est une chose que VOUS SEUL pouviez accomplir !");
                R(ref s, "What are you talking about, <E049><E003 4><E164 112 7 1 2 5 0 1 1><E118 112 1.2><E139 112>Ryunosuke?", "De quoi parles-tu donc, <E049><E003 4><E164 112 7 1 2 5 0 1 1><E118 112 1.2><E139 112>Ryunosuke ?");
                R(ref s, "As well as being a judge, <E049><E003 6>Mr Jigoku is also Japan's\r\n<E006>Minister of Foreign Affairs<E005>.", "En plus de sa fonction de magistrat, <E049><E003 6>M. Jigoku est aussi le\r\n<E006>ministre des Affaires étrangères<E005> du Japon.");
                R(ref s, "Which means <E049><E003 10><E025 2><E330>he's <E006>exempt<E005> from having his luggage\r\nsearched when he enters the country.", "Ce qui signifie <E049><E003 10><E025 2><E330>qu'il est <E006>exempté<E005> de toute fouille de bagages\r\nlorsqu'il pénètre sur le territoire.");
                R(ref s, "We learnt that <E145 1 0><E118 1 1.4><E149 1 0 8>when we first met you upon your\r\narrival in London.", "Nous l'avons appris <E145 1 0><E118 1 1.4><E149 1 0 8>lors de notre première rencontre à votre\r\narrivée à Londres.");
                R(ref s, "Well, <E049><E003 8>all those passport checks and luggage searches at\r\nthe border took rather a lot of time.", "Eh bien, <E049><E003 8>toutes ces vérifications de passeports et ces fouilles de bagages\r\nà la frontière ont pris un temps considérable.");
                R(ref s, "I must say, <E049><E003 8>I'm very envious of your ministerial status.<E049><E003 12>\r\n<E145 46 65><E118 46 0.7><E025 3>You didn't have to go through any of that, <E049><E003 6>did you?", "Je dois dire que <E049><E003 8>j'envie beaucoup votre statut ministériel.<E049><E003 12>\r\n<E145 46 65><E118 46 0.7><E025 3>Vous n'avez rien eu à subir de tout cela, <E049><E003 6>n'est-ce pas ?");
                R(ref s, "Ah, <E003 10><E341><E025 2>I knew you were jealous!<E049><E003 15>\r\n<E025 1><E145 47 68><E149 47 0 0><E169 47 0><E045>Hah <E003 9>hah <E003 9>hah <E003 9>hah <E003 9>hah!<E169 47 3>", "Ah, <E003 10><E341><E025 2>je savais bien que vous étiez jaloux !<E049><E003 15>\r\n<E025 1><E145 47 68><E149 47 0 0><E169 47 0><E045>Ha <E003 9>ha <E003 9>ha <E003 9>ha <E003 9>ha !<E169 47 3>");
                R(ref s, "I presume you recall this, <E049><E003 6><E025 3>Judge Jigoku?", "Je présume que vous vous en souvenez, <E049><E003 6><E025 3>juge Jigoku ?");
                return s;
            };

            // [48] BB\script\output\_sce04_c302_0020_eng#3
            entryTranslators[@"BB\script\output\_sce04_c302_0020_eng#3"] = (s) => {
                R(ref s, "It's a photograph we took in the foyer of the hotel to mark\r\nthe occasion.", "C'est une photographie que nous avons prise dans le hall de l'hôtel\r\npour marquer l'occasion.");
                R(ref s, "As the court will note, <E003 8><E025 3>you have with you <E003 6><E238>your large\r\n<E006>travel trunk<E005>.", "Comme la cour pourra le constater, <E003 8><E025 3>vous aviez avec vous <E003 6><E238>votre imposante\r\n<E006>malle de voyage<E005>.");
                R(ref s, "Large enough, <E049><E003 6>in fact, <E049><E003 6><E145 1 7><E003 7><E025 1><E092 1><E346>to have a corpse inside!", "Suffisamment grande, <E049><E003 6>en réalité, <E049><E003 6><E145 1 7><E003 7><E025 1><E092 1><E346>pour y cacher un cadavre !");
                R(ref s, "M-<E049><E003 10><E341>Mr Naruhodo!<E049><E003 14>\r\n<E338><E342>Surely you're not suggesting...?", "M-<E049><E003 10><E341>Monsieur Naruhodo !<E049><E003 14>\r\n<E338><E342>Vous n'êtes tout de même pas en train de suggérer... ?");
                R(ref s, "I'm afraid I am, <E049><E003 8>yes.", "J'en ai bien peur, <E049><E003 8>oui.");
                R(ref s, "Three days ago, <E049><E003 8>when we were chatting innocently with\r\nthe new arrivals from Japan in the hotel...", "Il y a trois jours, <E049><E003 8>pendant que nous bavardions innocemment à l'hôtel\r\navec la délégation venue du Japon...");
                R(ref s, "...the body of Inspector Gregson was just metres away\r\nfrom us, <E003 16><E025 1><E607><E339>inside Judge Jigoku's trunk!", "... le corps de l'inspecteur Gregson n'était qu'à quelques mètres\r\nde nous, <E003 16><E025 1><E607><E339>à l'intérieur de la malle du juge Jigoku !");
                R(ref s, "Order!<E049><E003 4> Order!<E049><E003 4> <E341><E025 1>Order in court!", "Silence !<E049><E003 4> Silence !<E049><E003 4> <E341><E025 1>Du calme dans la salle !");
                R(ref s, "I'm sceptical, <E049><E003 6>Counsel, <E049><E003 8><E025 2><E145 61 4><E118 61 0.6>that a grown man's body could fit\r\ninside even the largest travel trunk.", "Je doute fort, <E049><E003 6>Maître, <E049><E003 8><E025 2><E145 61 4><E118 61 0.6>que le corps d'un homme adulte puisse tenir\r\ndans une malle de voyage, fût-elle de belle taille.");
                R(ref s, "It could.", "Il le pouvait.");
                R(ref s, "Because I happen to know<E049><E003 15><E025 2><E070 2 1 1><E071><E300 120 0><E070 0 1 1><E043> that <E006>the witness himself<E005>,<E003 6> a man\r\nof considerable size, <E003 8>fits inside his trunk.", "Car il se trouve que je sais<E049><E003 15><E025 2><E070 2 1 1><E071><E300 120 0><E070 0 1 1><E043> que <E006>le témoin lui-même<E005>,<E003 6> un homme\r\npourtant d'un gabarit imposant, <E003 8>y tient parfaitement.");
                R(ref s, "And verifying that would be extremely simple...<E049><E003 13><E164 1 8 1 2 8 0 1 1><E139 1>\r\n<E025 1>wouldn't it, <E049><E003 8>Judge Jigoku?!", "Et vérifier cela serait d'une extrême simplicité...<E049><E003 13><E164 1 8 1 2 8 0 1 1><E139 1>\r\n<E025 1>n'est-ce pas, <E049><E003 8>juge Jigoku ?!");
                R(ref s, "But, <E049><E003 8>but inside his trunk...<E003 14>\r\n<E025 1><E331>How horrifying!", "Mais... <E049><E003 8>dans sa malle...<E003 14>\r\n<E025 1><E331>Quelle abomination !");
                R(ref s, "And after we'd spoken with you at the Great Waterloo\r\nHotel...", "Et après notre conversation au Grand Hôtel Waterloo...");
                R(ref s, "...you had the opportunity to visit the apparent ‘scene’ on\r\nFresno Street...", "... vous avez eu tout le loisir de vous rendre sur la prétendue « scène »\r\nde Fresno Street...");
                R(ref s, "...taking your trunk with you in a cab, <E049><E003 10><E025 1><E346>to deposit the\r\ninspector's body!", "... emportant votre malle en fiacre, <E049><E003 10><E025 1><E346>afin d'y déposer le corps\r\nde l'inspecteur !");
                R(ref s, "I don't have to listen <E341>to this nonsense!", "Je n'ai pas à écouter <E341>ces billevesées !");
                R(ref s, "Dr Gorey, <E049><E003 6>the coroner who examined the body, <E049><E003 6>has\r\nconfirmed the possibility.", "La Dre Gorey, <E049><E003 6>le médecin légiste ayant examiné le corps, <E049><E003 6>en a\r\nconfirmé la possibilité.");
                R(ref s, "She's acknowledged there are signs <E049><E003 8><E330>that steps may have\r\nbeen taken to <E006>disguise<E005> the true time of death.", "Elle a admis qu'il existait des indices <E049><E003 8><E330>montrant qu'on avait cherché\r\nà <E006>maquiller<E005> l'heure réelle de la mort.");
                R(ref s, "The onset of the body's decomposition could have been\r\ndelayed by storing it in a refrigerator.", "La décomposition du corps a pu être ralentie\r\nen le conservant dans un réfrigérateur.");
                R(ref s, "Counsel, <E049><E003 10><E025 2>as I remember explaining yesterday...", "Maître, <E049><E003 10><E025 2>il me semble avoir expliqué hier...");
                R(ref s, "...refrigerators of the requisite size are few and far\r\nbetween.", "... que les réfrigérateurs d'une telle contenance sont extrêmement rares.");
                R(ref s, "Yes, <E049><E003 6>I'm sure they are.<E049><E003 12> <E025 2>But one place they're certainly\r\nfound <E049><E003 8><E145 1 66><E118 1 1.3><E003 15><E330><E025 3>is on <E006>large ocean liners<E005>.", "Oui, <E049><E003 6>j'en conviens.<E049><E003 12> <E025 2>Mais il est un endroit où l'on en trouve\r\nà coup sûr : <E049><E003 8><E145 1 66><E118 1 1.3><E003 15><E330><E025 3>à bord des <E006>grands paquebots de ligne<E005>.");
                R(ref s, "Such ships are equipped with electrically refrigerated\r\ncold rooms to keep food fresh on their long sea voyages.", "Ces navires sont équipés de chambres froides électriques\r\npour conserver les denrées au frais durant les longues traversées.");
                R(ref s, "And the SS Grouse is no exception.", "Et le SS Grouse ne fait pas exception.");
                R(ref s, "Professor Mikotoba told me about it only yesterday.<E049><E003 10><E145 1 21><E003 10>\r\n<E330><E025 3>...Well, <E049><E003 8><E025 2>Judge Jigoku?", "Le professeur Mikotoba m'en a parlé hier encore.<E049><E003 10><E145 1 21><E003 10>\r\n<E330><E025 3>... Alors, <E049><E003 8><E025 2>juge Jigoku ?");
                return s;
            };

            // [49] BB\script\output\_sce04_c302_0020_eng#4
            entryTranslators[@"BB\script\output\_sce04_c302_0020_eng#4"] = (s) => {
                R(ref s, "However much you prolong this debate, <E049><E003 8>you can't\r\neliminate the truth.", "Vous aurez beau faire traîner ce débat, <E049><E003 8>vous ne pourrez pas\r\neffacer la vérité.");
                R(ref s, "All the evidence...<E049><E003 10><E025 1><E164 1 8 1 2 5 1 1 1><E139 1>points to you being the killer!", "Toutes les preuves...<E049><E003 10><E025 1><E164 1 8 1 2 5 1 1 1><E139 1>vous désignent comme le meurtrier !");
                R(ref s, "Ha <E003 4>ha <E003 4>ha <E003 4>ha <E003 4>ha <E003 4>ha <E003 4>ha<E025 0>h...", "Ha <E003 4>ha <E003 4>ha <E003 4>ha <E003 4>ha <E003 4>ha <E003 4>ha<E025 0>h...");
                R(ref s, "Well, <E049><E003 8><E025 2>this is all very heartening.", "Eh bien, <E049><E003 8><E025 2>tout ceci est très réjouissant.");
                R(ref s, "I can see that it was a wise move <E049><E003 10><E145 47 82><E117 47 25><E003 15><E025 3>letting Asogi and you\r\nembark on this study tour.", "Je vois que ce fut une sage décision <E049><E003 10><E145 47 82><E117 47 25><E003 15><E025 3>de vous envoyer, Asogi\r\net vous, dans ce voyage d'études.");
                R(ref s, "What are you talking about now?", "De quoi parlez-vous à présent ?");
                R(ref s, "Logical reasoning, <E049><E003 6>of course.", "Du raisonnement logique, <E049><E003 6>bien entendu.");
                R(ref s, "All court proceedings will be built on logical reasoning in\r\nthe new century.", "Toutes les procédures judiciaires reposeront sur la logique\r\nau siècle prochain.");
                R(ref s, "And I can see <E049><E003 18><E145 47 68><E118 47 1.35><E003 5><E045><E025 2>that you've both <E342>laid firm foundations for\r\nthat already!", "Et je constate <E049><E003 18><E145 47 68><E118 47 1.35><E003 5><E045><E025 2>que vous en avez tous deux <E342>déjà posé de solides fondations !");
                R(ref s, "Judge Jigoku, <E049><E003 6>please!<E049><E003 12> <E025 1>Stop diverting attention from the\r\nissue at hand!", "Juge Jigoku, <E049><E003 6>de grâce !<E049><E003 12> <E025 1>Cessez d'éluder la véritable\r\nquestion !");
                R(ref s, "The defence has made an accusation against you.<E049><E003 10><E164 9 83 1 2 5 0 1 1><E118 9 1.6><E139 9>\r\n<E025 1>How do you respond?!", "La défense a porté une accusation contre vous.<E049><E003 10><E164 9 83 1 2 5 0 1 1><E118 9 1.6><E139 9>\r\n<E025 1>Que répondez-vous ?!");
                R(ref s, "Respond?<E049><E003 15>\r\n<E025 2><E145 47 82><E003 6><E333>There's really no need for me to respond, <E049><E003 6>is there?", "Répondre ?<E049><E003 15>\r\n<E025 2><E145 47 82><E003 6><E333>Ai-je réellement besoin de répondre, <E049><E003 6>je vous prie ?");
                R(ref s, "Why ever not?", "Et pourquoi donc pas ?");
                R(ref s, "Because before you can even begin to answer the\r\nquestion of when the victim was killed...", "Parce qu'avant même de chercher à savoir quand la victime\r\na été tuée...");
                R(ref s, "...you must first establish one key fact:", "... vous devez d'abord établir un fait capital :");
                R(ref s, "<E043><E006>Where<E005> was the victim killed?<E049><E003 15>\r\n<E025 2>...It's quite logical.", "<E043><E006>Où<E005> la victime a-t-elle été tuée ?<E049><E003 15>\r\n<E025 2>... C'est pourtant logique.");
                R(ref s, "The actual scene of the crime...", "Le véritable lieu du crime...");
                R(ref s, "The prosecution's stance is unaltered.<E049><E003 8> <E145 112 0><E118 112 1.5><E003 15><E025 2>The killing took\r\nplace on Fresno Street when the gunshot was heard...", "La position de l'accusation reste inchangée.<E049><E003 8> <E145 112 0><E118 112 1.5><E003 15><E025 2>Le meurtre s'est\r\nproduit sur Fresno Street quand le coup de feu a retenti...");
                R(ref s, "...as the accused, <E049><E003 8>Barok van Zieks, <E049><E003 10><E346>shot the victim at\r\npoint-blank range!", "... lorsque l'accusé, <E049><E003 8>Drake Van Peers, <E049><E003 10><E346>a abattu la victime\r\nà bout portant !");
                R(ref s, "Since no tangible evidence exists to disprove the\r\nprosecution's claim at this time...", "Puisqu'aucun élément matériel ne vient contredire la thèse\r\nde l'accusation à cette heure...");
                R(ref s, "...the defence's deductions amount to little more than an\r\nelaborate fairy tale.", "... les déductions de la défense ne sont rien d'autre qu'un\r\nconte de fées élaboré.");
                R(ref s, "I'm afraid that's how the logical reasoning the British are\r\nknown for really works, <E049><E003 6><E025 3>young stripling.", "J'ai bien peur que ce soit ainsi que fonctionne la célèbre logique\r\nbritannique, <E049><E003 6><E025 3>jeune greluchet.");
                R(ref s, "The victim was shot in that little room on Fresno Street\r\nand died instantly?", "La victime aurait été abattue dans cette pièce de Fresno Street\r\net serait morte sur le coup ?");
                R(ref s, "I'm afraid it's the prosecution's claim...<E049><E003 15><E149 1 0 0><E330><E025 3>that's the only fairy\r\ntale here.", "J'ai bien peur que la thèse de l'accusation...<E049><E003 15><E149 1 0 0><E330><E025 3>soit le seul conte\r\nde fées ici présent.");
                R(ref s, "How can you say that?", "Comment pouvez-vous affirmer cela ?");
                R(ref s, "Quite simply...", "Tout simplement...");
                R(ref s, "Because that claim directly <E006>contradicts<E005> a certain piece of\r\nevidence in our possession.", "Parce que cette allégation <E006>contredit<E005> formellement une certaine\r\npièce à conviction en notre possession.");
                return s;
            };

            // [50] BB\script\output\_sce04_c302_0040_eng#2
            entryTranslators[@"BB\script\output\_sce04_c302_0040_eng#2"] = (s) => {
                R(ref s, "Very tantalising, Counsel.<E049><E003 10> <E025 2><E145 61 7><E118 61 0.7>I think you had better explain\r\nyourself to the court, <E003 4>don't you?", "Voilà qui est fort piquant, Maître.<E049><E003 10> <E025 2><E145 61 7><E118 61 0.7>Il conviendrait à présent de vous\r\nexpliquer devant ce tribunal, <E003 4>ne croyez-vous pas ?");
                return s;
            };

            // [51] BB\script\output\_sce04_c302_0040_eng#3
            entryTranslators[@"BB\script\output\_sce04_c302_0040_eng#3"] = (s) => {
                R(ref s, "The prosecution claims that Inspector Gregson died\r\ninstantly when he was shot at the scene on Fresno Street.", "L'accusation soutient que l'inspecteur Gregson a été tué sur\r\nle coup par balle sur les lieux, dans Fresno Street.");
                R(ref s, "But this evidence clearly contradicts that claim!", "Mais cette preuve contredit formellement cette thèse !");
                return s;
            };

            // [52] BB\script\output\_sce04_c302_0040_eng#4
            entryTranslators[@"BB\script\output\_sce04_c302_0040_eng#4"] = (s) => {
                R(ref s, "...The Japanese really are a curious breed.", "... Les Japonais sont décidément de curieux spécimens.");
                R(ref s, "To proffer an argument with such conviction, <E049><E003 8>only to\r\npresent such nonsensical evidence...", "Avancer une théorie avec tant d'assurance pour ensuite présenter\r\nune preuve aussi insensée...");
                R(ref s, "Perhaps my Japanese friend's inexplicable thinking <E049><E003 6><E145 112 4><E118 112 1.2><E003 20><E025 3><E238>is\r\nwhy people talk of the mystique of the East?", "La tournure d'esprit impénétrable de mon compatriote <E049><E003 6><E145 112 4><E118 112 1.2><E003 20><E025 3><E238>explique\r\nsans doute pourquoi l'on vante le mystère de l'Orient ?");
                R(ref s, "In case you hadn't noticed, <E049><E003 8><E025 3>I'm not the only Japanese\r\naround here.<E049><E003 10> <E025 3><E341>...Do you even have a mirror?", "Au cas où cela vous aurait échappé, <E049><E003 8><E025 3>je ne suis pas le seul Japonais\r\npar ici.<E049><E003 10> <E025 3><E341>... Vous arrive-t-il de vous regarder dans une glace ?");
                R(ref s, "The court is not interested in the mystique of anything.<E049><E003 12>\r\nYou will be penalised accordingly.<E283><E282>", "Ce tribunal ne s'intéresse à aucun prétendu mystère.<E049><E003 12>\r\nVous recevrez une pénalité en conséquence.<E283><E282>");
                R(ref s, "(Was the victim killed in the room on Fresno Street,<E003 8> or\r\nwas he moved there after his death...?)", "(La victime a-t-elle été tuée sur Fresno Street,<E003 8> ou y a-t-elle\r\nété transportée après sa mort... ?)");
                R(ref s, "(There's one piece of evidence we have that shows the\r\nanswer to that question surprisingly clearly!)", "(Il y a une pièce à conviction qui tranche cette question avec une clarté\r\nsurprenante !)");
                R(ref s, "Perhaps you should try <E049><E003 6><E164 9 15 1 2 6 0 0 1><E139 9>to present the correct one this\r\ntime then, <E003 6>Mr Naruhodo!", "Peut-être devriez-vous tâcher <E049><E003 6><E164 9 15 1 2 6 0 0 1><E139 9>de présenter la bonne pièce cette\r\nfois, <E003 6>monsieur Naruhodo !");
                R(ref s, "Are you going to try again?<E049><E003 10>\r\n<E025 2>Or can't you hold your hand steady enough to point it out?", "Allez-vous retenter votre chance ?<E049><E003 10>\r\n<E025 2>Ou votre main tremble-t-elle trop pour la désigner ?");
                return s;
            };

            // [53] BB\script\output\_sce04_c302_0040_eng#5
            entryTranslators[@"BB\script\output\_sce04_c302_0040_eng#5"] = (s) => {
                R(ref s, "A photograph of the victim in the very location you claim\r\nhe wasn't killed?", "Une photo de la victime à l'endroit même où vous affirmez\r\nqu'elle n'a pas été tuée ?");
                R(ref s, "Yes!<E049><E003 12> <E025 3>But the point is <E049><E003 10><E025 2><E333><E006>the posture<E005> of the body itself.", "Oui !<E049><E003 12> <E025 3>Mais l'élément capital réside dans <E049><E003 10><E025 2><E333><E006>la posture<E005> du corps lui-même.");
                R(ref s, "If Inspector Gregson had been shot there in that room...", "Si l'inspecteur Gregson avait été abattu dans cette pièce...");
                R(ref s, "...it's out of the question <E049><E003 10><E300 85 0><E607><E025 1>that his body would have been\r\n<E006>curled up<E005> in a ball like that!", "... il est totalement impensable <E049><E003 10><E300 85 0><E607><E025 1>que son corps se soit retrouvé\r\n<E006>recroquevillé<E005> de la sorte !");
                R(ref s, "I'm sorry to disappoint you, <E049><E003 6><E025 2><E145 47 81><E144 47><E239>but your logic is flawed.", "Navré de vous décevoir, <E049><E003 6><E025 2><E145 47 81><E144 47><E239>mais votre raisonnement est vicié.");
                R(ref s, "He could easily have adopted that foetal position due to\r\nthe pain of the shot which subsequently proved fatal.", "Il a très bien pu adopter cette position fœtale sous l'effet de\r\nla douleur du coup de feu qui lui a été fatal.");
                R(ref s, "I'm sorry to disappoint you, <E049><E003 6>Judge Jigoku, <E049><E003 10><E025 2>but it's your\r\nlogic that is flawed.", "Navré de vous décevoir, <E049><E003 6>juge Jigoku, <E049><E003 10><E025 2>mais c'est votre\r\nlogique qui fait défaut.");
                R(ref s, "According to this autopsy report, <E049><E003 8><E025 3>the victim <E006>died instantly<E005>.", "D'après ce rapport d'autopsie, <E049><E003 8><E025 3>la victime est <E006>morte sur le coup<E005>.");
                R(ref s, "He would have felt no pain, <E049><E003 10><E333>much less have been able to\r\ndraw himself into that position.", "Il n'a ressenti aucune douleur, <E049><E003 10><E333>et n'aurait encore moins pu\r\nse replier dans une telle posture.");
                R(ref s, "Which begs the question of <E049><E003 8><E025 3>why the victim's body is\r\ncurled up in that way.", "Ce qui soulève la question de savoir <E049><E003 8><E025 3>pourquoi son corps était\r\nainsi recroquevillé.");
                R(ref s, "Though the answer should be abundantly clear by now.", "Bien que la réponse doive désormais crever les yeux.");
                R(ref s, "You're, <E049><E003 8><E025 3><E145 61 5><E118 61 0.6><E342>you're suggesting...", "Vous... <E049><E003 8><E025 3><E145 61 5><E118 61 0.6><E342>vous insinuez que...");
                R(ref s, "The inspector's body took on that posture ahead of its\r\narrival on Fresno Street...", "Le corps de l'inspecteur a pris ce pli bien avant son arrivée\r\nsur Fresno Street...");
                R(ref s, "...before it was coldly <E006>turned out<E005> on the floor...<E049><E003 15><E025 1><E164 1 9 1 2 5 0 2 1><E139 1><E092 1>from the\r\ninside of a large travel trunk!", "... avant d'être froidement <E006>déversé<E005> sur le plancher...<E049><E003 15><E025 1><E164 1 9 1 2 5 0 2 1><E139 1><E092 1>depuis\r\nle fond d'une grande malle de voyage !");
                R(ref s, "Y-<E049><E003 8>You're quite right...<E049><E003 12>\r\n<E025 3>The shape of the body...", "V-<E049><E003 8>Vous avez parfaitement raison...<E049><E003 12>\r\n<E025 3>La forme du corps...");
                R(ref s, "It looks exactly as if it had been kept in <E006>a confined space<E005>!", "On dirait vraiment qu'il est resté enfermé dans <E006>un espace exigu<E005> !");
                R(ref s, "Judge Jigoku, <E049><E003 10><E025 1><E335>present your trunk for examination!", "Juge Jigoku, <E049><E003 10><E025 1><E335>mettez votre malle à la disposition de la cour !");
                R(ref s, "I believe it's very possible that it will contain traces<E049><E003 10> <E025 1><E549 7 20 3 1><E131><E046>of the\r\nvictim's <E006>blood<E005>!", "Je suis convaincu qu'elle contient des traces<E049><E003 10> <E025 1><E549 7 20 3 1><E131><E046>du <E006>sang<E005>\r\nde la victime !");
                R(ref s, "Present my trunk?<E049><E003 13>\r\n<E025 1><E045><E149 47 6 0>I refuse!", "Présenter ma malle ?<E049><E003 13>\r\n<E025 1><E045><E149 47 6 0>Je refuse !");
                R(ref s, "On what grounds?", "À quel titre ?");
                R(ref s, "I'm the Minister of Foreign Affairs <E341>from the Empire of\r\nJapan!", "Je suis le ministre des Affaires étrangères <E341>de l'Empire\r\ndu Japon !");
                R(ref s, "I shouldn't have to put up with this treatment<E049><E003 10><E025 1><E046><E149 47 0 0> just because\r\nof some stripling's baseless accusations!", "Je n'ai pas à subir de tels outrages<E049><E003 10><E025 1><E046><E149 47 0 0> pour les simples\r\ndélires sans fondement d'un greluchet !");
                R(ref s, "In other words, <E049><E003 8><E025 2><E145 9 83><E118 9 1.5><E139 9><E338>Judge Jigoku...", "Autrement dit, <E049><E003 8><E025 2><E145 9 83><E118 9 1.5><E139 9><E338>juge Jigoku...");
                R(ref s, "...there is blood in your trunk!", "... il y a du sang dans votre malle !");
                R(ref s, "I decline to answer that.", "Je refuse de répondre.");
                R(ref s, "As the Minister of Foreign Affairs, <E049><E003 8>I have privileges that\r\nallow me to–", "En tant que ministre des Affaires étrangères, <E049><E003 8>mes privilèges\r\nm'autorisent à...");
                R(ref s, "At this moment, <E049><E003 8>you're not a government minister.", "En cet instant, <E049><E003 8>vous n'êtes pas ministre.");
                R(ref s, "You are a witness in a trial in Britain's highest court!", "Vous êtes témoin au procès de la plus haute cour de Grande-Bretagne !");
                R(ref s, "I don't care who you are <E049><E003 8>or what your status outside this\r\ncourtroom might be, <E049><E003 10><E025 1>you will NOT withhold information!", "Peu m'importe qui vous êtes <E049><E003 8>ou vos titres en dehors de cette salle,<E049><E003 10>\r\n<E025 1>vous ne dissimulerez AUCUNE information !");
                R(ref s, "Nothing is more important than the truth!", "Rien n'est plus important que la vérité !");
                return s;
            };

            // [54] BB\script\output\_sce04_c302_0040_eng#6
            entryTranslators[@"BB\script\output\_sce04_c302_0040_eng#6"] = (s) => {
                R(ref s, "We've wasted enough time!", "Nous avons perdu assez de temps !");
                R(ref s, "It's clear to me <E049><E003 8><E025 2>that any further discussion of this case will\r\nbe fruitless.", "Il m'apparaît clairement <E049><E003 8><E025 2>que tout débat prolongé sur cette affaire sera\r\ninfructueux.");
                R(ref s, "Barok van Zieks, <E049><E003 8><E025 2>I would like to think that however\r\nmisguided...", "Drake Van Peers, <E049><E003 8><E025 2>j'ose croire que, si fourvoyé fussiez-vous...");
                R(ref s, "...you acted out of a sense of justice nonetheless.<E049><E003 12>\r\n<E025 3>Though it pains me to have reached this conclusion...", "... vous avez néanmoins agi selon votre sens de la justice.<E049><E003 12>\r\n<E025 3>Bien qu'il me soit douloureux d'en arriver là...");
                R(ref s, "Wait, My Lord!", "Attendez, Votre Honneur !");
                R(ref s, "In accordance with the findings of this court, <E049><E003 6><E025 3>I hereby\r\npronounce the defendant, <E049><E003 6><E025 3>Barok van Zieks...", "Conformément aux conclusions de ce tribunal, <E049><E003 6><E025 3>je déclare\r\npar la présente l'accusé, <E049><E003 6><E025 3>Drake Van Peers...");
                R(ref s, "That concludes business.<E049><E003 10>\r\n<E025 2>Court is adjourned!", "La séance est levée.<E049><E003 10>\r\n<E025 2>L'audience est terminée !");
                return s;
            };

            // [55] BB\script\output\_sce04_c302_0050_eng#2
            entryTranslators[@"BB\script\output\_sce04_c302_0050_eng#2"] = (s) => {
                R(ref s, "Order!<E049><E003 4> <E025 1>Order in court!<E049><E003 13>\r\n<E025 2><E145 61 5><E118 61 0.65>Well, Mr Jigoku...<E003 12><E025 1><E045>what's it to be?", "Silence !<E049><E003 4> <E025 1>Du calme dans la salle !<E049><E003 13>\r\n<E025 2><E145 61 5><E118 61 0.65>Alors, monsieur Jigoku...<E003 12><E025 1><E045>qu'en est-il ?");
                R(ref s, "You can't be serious!<E049><E003 8><E145 112 7><E118 112 0.65><E139 112>\r\n<E338><E025 1>You did it?!", "Ce n'est pas possible !<E049><E003 8><E145 112 7><E118 112 0.65><E139 112>\r\n<E338><E025 1>C'était vous ?!");
                R(ref s, "Have you no shame at all...<E003 12>Kazuma Asogi?", "N'avez-vous donc aucune honte...<E003 12>Kazuma Asogi ?");
                R(ref s, "Very well, <E049><E003 6>I admit it.", "C'est bon, <E049><E003 6>je l'admets.");
                R(ref s, "I did bring the inspector's body into the country.", "C'est bien moi qui ai fait entrer le corps de l'inspecteur sur ce sol.");
                R(ref s, "Inside my trunk...<E049><E003 12><E025 2><E341><E338>exactly as postulated by the defence.", "Dans ma malle...<E049><E003 12><E025 2><E341><E338>exactement comme la défense l'a affirmé.");
                R(ref s, "Dear God!<E049><E003 16> <E025 1><E341>Outrageous!", "Grand Dieu !<E049><E003 16> <E025 1><E341>C'est inouï !");
                R(ref s, "So it WAS you!<E049><E003 15> <E025 1>You admit to Inspector Gregson's mur–", "C'était donc bien VOUS !<E049><E003 15> <E025 1>Vous reconnaissez le meurtre de l'inspecteur Gre...");
                R(ref s, "No!<E049><E003 15> <E239><E025 2>I admit to nothing more than what I've said.", "Non !<E049><E003 15> <E239><E025 2>Je n'admets rien de plus que mes propres déclarations.");
                R(ref s, "Of killing the man, <E049><E003 12><E025 2><E145 47 82><E238>I certainly have no recollection.", "D'avoir tué cet homme, <E049><E003 12><E025 2><E145 47 82><E238>je n'en ai absolument aucun souvenir.");
                R(ref s, "What on earth is that cryptic statement supposed to mean?", "Que signifie cette déclaration pour le moins énigmatique ?");
                R(ref s, "I merely disposed of the inspector's body, <E049><E003 8><E025 3>which was left\r\nin my cabin.", "Je me suis contenté de faire disparaître le corps de l'inspecteur, <E049><E003 8><E025 3>laissé\r\ndans ma cabine.");
                R(ref s, "In order to avoid unwanted attention.", "Afin d'éviter tout soupçon importun.");
                R(ref s, "As the judicial assistant over there pointed out,<E049><E003 8> <E025 3>I had no\r\nchance to throw it into the ocean.", "Comme l'a relevé la jeune assistante juridique,<E049><E003 8> <E025 3>je n'avais aucune\r\npossibilité de le jeter par-dessus bord.");
                R(ref s, "So...<E049><E003 12>I decided my only option was to bring it into Britain\r\nwith me and dispose of it somewhere else.", "Alors...<E049><E003 12>j'ai jugé que mon seul recours était de l'amener en Grande-Bretagne\r\npour m'en débarrasser ailleurs.");
                R(ref s, "You, <E049><E003 8><E025 1><E345><E342>you can't still deny it!<E049><E003 10> <E025 2>If you didn't do it,<E049><E003 5> <E025 1><E164 1 71 1 2 8 0 2 1><E118 1 1.2><E139 1>then who on\r\nearth did kill the man?!", "Vous... <E049><E003 8><E025 1><E345><E342>vous ne pouvez pas continuer à nier !<E049><E003 10> <E025 2>Si ce n'est pas vous,<E049><E003 5> <E025 1><E164 1 71 1 2 8 0 2 1><E118 1 1.2><E139 1>qui\r\ndiable l'a abattu ?!");
                R(ref s, "As you know, <E049><E003 10><E330><E025 2>there was one other person in my cabin\r\nthat night.<E049><E003 10> <E025 3>He had <E006>the opportunity<E005>.", "Comme vous le savez, <E049><E003 10><E330><E025 2>il y avait une autre personne dans ma cabine\r\ncette nuit-là.<E049><E003 10> <E025 3>Elle en a eu <E006>l'occasion<E005>.");
                R(ref s, "And moreover, <E049><E003 12><E239><E025 3>he'd already accepted <E006>a mission<E005> to take\r\nthe inspector's life.", "Et qui plus est, <E049><E003 12><E239><E025 3>elle avait accepté <E006>la mission<E005> d'ôter la vie\r\nà cet inspecteur.");
                R(ref s, "That's right!<E049><E003 12> <E025 1>Who else could it have been?!<E049><E003 8>\r\n<E025 2><E145 47 86><E003 10>It was you...<E003 14><E025 1><E046>Kazuma Asogi!", "C'est exact !<E049><E003 12> <E025 1>Qui d'autre cela pouvait-il être ?!<E049><E003 8>\r\n<E025 2><E145 47 86><E003 10>C'était vous...<E003 14><E025 1><E046>Kazuma Asogi !");
                R(ref s, "I never thought you'd stoop to this, <E049><E003 10><E025 1><E332>Seishiro Jigoku.", "Je ne vous aurais jamais cru capable d'une telle bassesse, <E049><E003 10><E025 1><E332>Seishiro Jigoku.");
                R(ref s, "You've taken the words straight out of my mouth...<E049><E003 12>\r\n<E025 4>‘Prosecutor’ <E049><E003 8><E025 3>Kazuma Asogi.", "C'est exactement ce que j'allais dire...<E049><E003 12>\r\n<E025 4>« Procureur » <E049><E003 8><E025 3>Kazuma Asogi.");
                R(ref s, "You thought by leaving the body in my cabin you could\r\npin the crime on me, <E049><E003 6><E025 3>did you?", "Vous pensiez qu'en abandonnant le corps dans ma cabine,\r\nvous pourriez m'imputer le crime, <E049><E003 6><E025 3>n'est-ce pas ?");
                R(ref s, "Well...<E049><E003 12><E025 2><E145 61 7><E118 61 0.6>the prosecution counsel has already admitted to\r\nvisiting the witness's cabin on the night in question.", "Eh bien...<E049><E003 12><E025 2><E145 61 7><E118 61 0.6>le représentant du ministère public a déjà reconnu\r\ns'être rendu dans la cabine du témoin la nuit des faits.");
                R(ref s, "Yes, <E049><E003 12><E333>on <E006>an assassination mission<E005>, <E049><E003 10><E025 2>no less.", "Oui, <E049><E003 12><E333>pour <E006>une mission d'assassinat<E005>, <E049><E003 10><E025 2>rien de moins.");
                R(ref s, "You, <E049><E003 10><E025 3><E341>you wouldn't...", "Vous... <E049><E003 10><E025 3><E341>vous n'oseriez pas...");
                R(ref s, "So...<E003 10>what do you make of that, <E049><E003 10><E025 1><E332>young stripling?", "Alors...<E003 10>qu'avez-vous à répondre à cela, <E049><E003 10><E025 1><E332>jeune greluchet ?");
                R(ref s, "You've heard my testimony now.<E049><E003 8> <E025 2>And that's all I have to\r\nsay on the matter.<E049><E003 13> <E136 47 83 3><E117 47 25><E118 47 0.75><E003 20><E025 1>I'll admit to nothing more!", "Vous avez entendu ma déposition.<E049><E003 8> <E025 2>Et c'est tout ce que j'ai à\r\ndire à ce sujet.<E049><E003 13> <E136 47 83 3><E117 47 25><E118 47 0.75><E003 20><E025 1>Je n'admettrai rien de plus !");
                R(ref s, "I, <E049><E003 10>I don't believe this...", "Je... <E049><E003 10>je n'y crois pas...");
                R(ref s, "Counsel for the Defence...", "Maître Naruhodo...");
                R(ref s, "...what is your position now?<E049><E003 10> <E025 2>The court awaits your\r\nresponse to the witness's assertion.", "... quelle est votre position désormais ?<E049><E003 10> <E025 2>Le tribunal attend votre\r\nréponse aux affirmations du témoin.");
                R(ref s, "The assertion that on the night in question, <E049><E003 10><E025 3>the victim's\r\nassailant was in fact <E006>Mr Kazuma Asogi<E005>.", "L'affirmation selon laquelle, la nuit en question, <E049><E003 10><E025 3>l'agresseur de la\r\nvictime n'était autre que <E006>M. Kazuma Asogi<E005>.");
                R(ref s, "(This isn't the dead end it seems to be.<E003 12>\r\n<E025 2><E338><E341>The answer's right in front of me.)", "(Ce n'est pas l'impasse que cela semble être.<E003 12>\r\n<E025 2><E338><E341>La réponse se trouve sous mes yeux.)");
                R(ref s, "(It comes down to Jigoku...<E003 12>or Kazuma.)", "(Tout se résume à Jigoku...<E003 12>ou Kazuma.)");
                R(ref s, "(Both of them had <E006>the opportunity<E007> to kill Gregson,<E003 10> <E025 3>but\r\nonly one of them did it.)", "(Tous deux avaient <E006>l'occasion<E007> de tuer Gregson,<E003 10> <E025 3>mais\r\nun seul des deux est passé à l'acte.)");
                R(ref s, "(And I'm just <E006>a step away<E007> <E003 10><E025 1><E332>from proving who!)", "(Et je ne suis plus qu'à <E006>un pas<E007> <E003 10><E025 1><E332>de prouver qui !)");
                return s;
            };

            // [56] BB\script\output\_sce04_c302_0060_eng#2
