            // [58] BB\script\output\_sce04_c302_0060_eng#4
            entryTranslators[@"BB\script\output\_sce04_c302_0060_eng#4"] = (s) => {
                R(ref s, "Well, <E049><E003 10><E145 1 7><E144 1><E330><E025 2>it is possible, <E049><E003 6>My Lord.", "Eh bien, <E049><E003 10><E145 1 7><E144 1><E330><E025 2>c'est une possibilité, <E049><E003 6>Votre Honneur.");
                R(ref s, "Wha...?!<E049><E003 18>\r\n<E025 3><E341>How could you?!", "Quo... ?!<E049><E003 18>\r\n<E025 3><E341>Comment peux-tu ?!");
                R(ref s, "Do you think I want to believe it?!<E049><E003 15>\r\n<E025 3>But the fact is...", "Tu crois que j'ai envie d'y croire ?!<E049><E003 15>\r\n<E025 3>Mais le fait est que...");
                R(ref s, "...I can't say with complete certainty what actually\r\nhappened <E049><E003 8><E025 1><E164 1 8 1 2 8 0 1 1><E139 1>because I wasn't there!", "... je ne peux affirmer avec certitude ce qui s'est passé<E049><E003 8>\r\n<E025 1><E164 1 8 1 2 8 0 1 1><E139 1>puisque je n'y étais pas !");
                R(ref s, "You...<E003 15> You disappoint me, <E049><E003 10><E025 1><E345>Ryunosuke!", "Tu...<E003 15> Tu me déçois, <E049><E003 10><E025 1><E345>Ryunosuke !");
                R(ref s, "If I may, <E049><E003 8>Mr Naruhodo...", "Si je puis me permettre, <E049><E003 8>monsieur Naruhodo...");
                R(ref s, "...I think perhaps that's why we form opinions based on\r\nevidence.", "... je pense que c'est précisément pour cela que nous nous basons\r\nsur les preuves.");
                R(ref s, "(So true...)", "(C'est tellement vrai...)");
                R(ref s, "(And actually, <E003 8><E025 1><E338><E341>we have evidence that can settle this\r\nargument conclusively!)", "(Et en réalité, <E003 8><E025 1><E338><E341>nous possédons une preuve capable de trancher\r\nce litige de façon irréfutable !)");
                R(ref s, "My Lord!<E049><E003 10> The defence would like to present evidence\r\nin support of–", "Votre Honneur !<E049><E003 10> La défense souhaiterait présenter une preuve\r\nà l'appui de...");
                R(ref s, "Before you plough on, <E049><E003 8>feigning ignorance of what just\r\noccurred, <E049><E003 6>Counsel...", "Avant d'aller plus loin en feignant d'ignorer ce qui vient de\r\nse produire, <E049><E003 6>Maître...");
                R(ref s, "...you must be penalised for that short but embarrassing\r\n<E049><E003 10><E333>‘Ah!’ <E049><E003 10>you uttered a moment ago.<E283><E282>", "... vous devez être sanctionné pour ce bref mais embarrassant\r\n<E049><E003 10><E333>« Ah ! » <E049><E003 10>que vous venez de pousser.<E283><E282>");
                R(ref s, "(Uuugh...<E003 10> I really thought I could just brush past it if I was\r\nquick enough...)", "(Ouuuh...<E003 10> Je pensais vraiment pouvoir faire comme si de rien n'était...)");
                R(ref s, "Never mind the penalty, Mr Naruhodo!<E049><E003 16>\r\n<E025 1><E346>The truth is all that matters!", "Peu importe la pénalité, monsieur Naruhodo !<E049><E003 16>\r\n<E025 1><E346>Seule la vérité importe !");
                return s;
            };

            // [59] BB\script\output\_sce04_c302_0060_eng#5
            entryTranslators[@"BB\script\output\_sce04_c302_0060_eng#5"] = (s) => {
                R(ref s, "Judge Jigoku!<E049><E003 15> <E025 2>Let me remind you of something you said\r\nonly a few minutes ago.", "Juge Jigoku !<E049><E003 15> <E025 2>Permettez-moi de vous rappeler vos propres propos\r\nd'il y a quelques instants.");
                R(ref s, "You claimed that logical reasoning is the future of the\r\njudicial process.", "Vous avez soutenu que le raisonnement logique est l'avenir\r\nde la procédure judiciaire.");
                R(ref s, "It is.<E049><E003 10> No question.", "C'est le cas.<E049><E003 10> Sans l'ombre d'un doute.");
                R(ref s, "Well, <E049><E003 8><E025 2>logical reasoning can prove something here.", "Eh bien, <E049><E003 8><E025 2>le raisonnement logique peut démontrer une chose ici.");
                R(ref s, "Namely, <E049><E003 7><E145 1 21><E003 15><E330><E025 2>that it would have been <E006>impossible<E005> for\r\nProsecutor Asogi to commit the crime.", "À savoir <E049><E003 7><E145 1 21><E003 15><E330><E025 2>qu'il aurait été <E006>impossible<E005> au procureur\r\nAsogi de commettre ce meurtre.");
                return s;
            };

