            };

            // [63] BB\script\output\_sce04_c302_0070_eng#4
            entryTranslators[@"BB\script\output\_sce04_c302_0070_eng#4"] = (s) => {
                R(ref s, "You're making the evidence weep here, <E049><E003 6>Ryunosuke\r\nNaruhodo.", "Tu fais pleurer les pièces à conviction, <E049><E003 6>Ryunosuke\r\nNaruhodo.");
                R(ref s, "Sorry?!", "Pardon ?!");
                R(ref s, "Every piece of evidence has a role to play in arriving at\r\nthe truth.", "Chaque élément de preuve a un rôle à jouer dans la quête de vérité.");
                R(ref s, "They're not playthings you can toss around the courtroom\r\nfor entertainment!", "Ce ne sont pas des jouets que l'on jette dans l'arène pour amuser\r\nla galerie !");
                R(ref s, "AAAAAAGH!<E345><E283><E282>", "AAAAAARGH !<E345><E283><E282>");
                R(ref s, "Never mind the evidence, <E049><E003 10><E331><E025 1>you're about to make me weep,\r\nMr Naruhodo!", "Sans parler des preuves, <E049><E003 10><E331><E025 1>c'est moi que vous allez faire pleurer,\r\nmonsieur Naruhodo !");
                R(ref s, "(Oh no!<E003 12> <E025 2>I can't upset Susato-san...<E003 12><E025 1><E341>or I'll end up being upset,\r\ntoo!)", "(Oh non !<E003 12> <E025 2>Je ne peux pas contrarier Susato...<E003 12><E025 1><E341>ou je vais finir en pleurs\r\nmoi aussi !)");
                R(ref s, "(We know a member of the crew was on <E006>sentry duty<E007>\r\noutside the first-class cabins nearly all the time.)", "(Nous savons qu'un membre d'équipage montait la <E006>garde<E007> devant les cabines\r\nde première classe presque continuellement.)");
                R(ref s, "(So as long as the guard was there, <E003 4>it would have been\r\nimpossible to fire a shot without it being heard.)", "(Tant que la sentinelle était là, <E003 4>il était impossible de tirer un coup\r\nde feu sans qu'il soit entendu.)");
                R(ref s, "(And that very much narrows down when the crime\r\ncould have been committed...)", "(Et cela restreint considérablement le moment où le crime a pu\r\nêtre commis...)");
                return s;
            };

            // [64] BB\script\output\_sce04_c302_0070_eng#5
            entryTranslators[@"BB\script\output\_sce04_c302_0070_eng#5"] = (s) => {
                R(ref s, "This itinerary for crew members of the SS Grouse, <E003 4>My\r\nLord.<E049><E003 14> <E025 2><E333>This is conclusive proof!", "Cet itinéraire des membres d'équipage du SS Grouse, <E003 4>Votre\r\nHonneur.<E049><E003 14> <E025 2><E333>En voici la preuve irréfutable !");
                R(ref s, "An itinerary?<E049><E003 10> How does that prove anything?", "Un itinéraire ?<E049><E003 10> En quoi cela prouve-t-il quoi que ce soit ?");
                R(ref s, "Judge Jigoku!<E049><E003 12> <E025 2>The moment you acknowledged that you\r\nfound the victim's body in your cabin...", "Juge Jigoku !<E049><E003 12> <E025 2>Dès l'instant où vous avez reconnu avoir trouvé\r\nle corps de la victime dans votre cabine...");
                R(ref s, "...this itinerary <E049><E003 5><E145 1 21><E003 13><E025 2><E330>suddenly became <E006>much more significant<E005>!", "... cet itinéraire <E049><E003 5><E145 1 21><E003 13><E025 2><E330>a pris <E006>une importance capitale<E005> !");
                R(ref s, "On the night in question, <E049><E003 8>as always, <E049><E003 6>a crewman sentry\r\nwas on guard outside your cabin door.", "La nuit des faits, <E049><E003 8>comme toujours, <E049><E003 6>un matelot montait la garde\r\ndevant la porte de votre cabine.");
                R(ref s, "As long as he was there, <E049><E003 8><E025 2>nobody could have fired a shot\r\ninside the cabin.", "Tant qu'il était présent, <E049><E003 8><E025 2>personne n'aurait pu tirer un coup\r\nde feu à l'intérieur.");
                R(ref s, "Absolutely.<E049><E003 12> <E025 2><E238>Because it's <E006>inconceivable<E005> that the guard\r\nwouldn't have heard it and come to investigate.", "Absolument.<E049><E003 12> <E025 2><E238>Il est <E006>inconcevable<E005> que le garde ne l'ait pas\r\nentendu et ne soit pas venu aux nouvelles.");
                R(ref s, "So that tells us <E049><E003 8><E025 3>that the crime must have taken place\r\nwhen the guard was elsewhere.", "Cela nous indique donc <E049><E003 8><E025 3>que le crime a nécessairement eu lieu\r\nquand le garde était ailleurs.");
                R(ref s, "And that narrows it down to <E006>the twenty minutes<E005> just after\r\nten o'clock, <E049><E003 6>as indicated on the itinerary.", "Et cela restreint le créneau <E006>aux vingt minutes<E005> qui ont suivi\r\ndix heures du soir, <E049><E003 6>comme l'indique l'itinéraire.");
                R(ref s, "Yes, <E049><E003 8><E025 2>I see no flaw in your reasoning so far.", "En effet, <E049><E003 8><E025 2>je ne vois nulle faille dans votre raisonnement jusqu'ici.");
                R(ref s, "But the crucial point is this:<E049><E003 10> when the evacuation drill\r\ntook place...", "Mais le point crucial est le suivant :<E049><E003 10> au moment de l'exercice\r\nd'évacuation...");
                R(ref s, "...the steamship had already <E006>put to sea<E005> from the port of\r\nDunkirk.", "... le paquebot avait déjà <E006>pris le large<E005> depuis le port\r\nde Dunkerque.");
                R(ref s, "Now, <E049><E003 8><E025 2>clearly the murder could only have been committed\r\nby <E006>somebody who was aboard the vessel<E005> at the time.", "Dès lors, <E049><E003 8><E025 2>le meurtre ne pouvait être commis que par\r\n<E006>une personne se trouvant à bord du navire<E005> à ce moment-là.");
                R(ref s, "But Prosecutor Asogi stated in yesterday's proceedings...", "Or le procureur Asogi a affirmé lors des débats d'hier...");
                R(ref s, "I didn't come to Great Britain to take anyone's life.", "Je ne suis pas venu en Grande-Bretagne pour ôter la vie à quiconque.");
                R(ref s, "So I left Gregson <E049><E003 8><E025 3>and disembarked the ship.", "J'ai donc laissé Gregson <E049><E003 8><E025 3>et j'ai débarqué du navire.");
                R(ref s, "I spent that night at a boarding house in the town,<E049><E003 8> and\r\nreturned to England the following morning.", "J'ai passé la nuit dans une auberge de la ville,<E049><E003 8> et\r\nje suis rentré en Angleterre le lendemain matin.");
                R(ref s, "Which I'm sure the court will agree is conclusive proof...", "Ce qui constitue, la cour en conviendra assurément, la preuve irréfutable...");
                R(ref s, "...that Kazuma Asogi <E049><E003 13><E025 1><E607><E006>couldn't possibly<E005> have carried out the\r\nkilling!", "... que Kazuma Asogi <E049><E003 13><E025 1><E607><E006>ne pouvait absolument pas<E005> avoir commis\r\nce meurtre !");
                R(ref s, "GYAAAAAAAAAGH<E345>!!!", "GYAAAAAAAAARGH<E345> !!!");
                R(ref s, "No!<E049><E003 14> <E025 1><E335>Absolutely not!<E049><E003 10><E145 47 86><E118 47 1.2><E003 8>\r\n<E025 1><E045>I don't accept that at all!", "Non !<E049><E003 14> <E025 1><E335>Absolument pas !<E049><E003 10><E145 47 86><E118 47 1.2><E003 8>\r\n<E025 1><E045>Je refuse d'admettre une chose pareille !");
                R(ref s, "What do you mean?", "Que voulez-vous dire ?");
                R(ref s, "The boy's just saying that to exonerate himself!<E049><E003 14>\r\n<E025 1><E046>We can't trust that he really disembarked the vessel!", "Ce jeune homme dit cela uniquement pour se disculper !<E049><E003 14>\r\n<E025 1><E046>Rien ne prouve qu'il a véritablement quitté le navire !");
                R(ref s, "Obviously after he left my cabin, <E049><E003 10><E025 1><E607>he hid himself\r\nsomewhere nearby on the ship.", "Après avoir quitté ma cabine, <E049><E003 10><E025 1><E607>il s'est tapi\r\nquelque part non loin à bord !");
                R(ref s, "Just waiting!<E049><E003 12> <E025 2>Waiting for his chance to come back and\r\nfinish the–", "Il guettait !<E049><E003 12> <E025 2>Il guettait l'occasion de revenir et d'en\r\nfinir avec...");
                R(ref s, "No, <E049><E003 8><E025 2>that's out of the question.", "Non, <E049><E003 8><E025 2>c'est tout à fait exclu.");
                R(ref s, "Isn't it, <E049><E003 6>Kazuma?", "N'est-ce pas, <E049><E003 6>Kazuma ?");
                R(ref s, "...As the defence rightly recalls...", "... Comme la défense le rappelle à juste titre...");
                R(ref s, "...I disembarked the vessel and spent the night in a\r\nboarding house in Dunkirk.", "... j'ai débarqué du navire et j'ai passé la nuit dans une\r\npension de famille à Dunkerque.");
                R(ref s, "And as I said yesterday, <E049><E003 10><E025 3><E238>I <E006>signed my name<E005> in the\r\naccommodation's register book.", "Et comme je l'ai déclaré hier, <E049><E003 10><E025 3><E238>j'ai <E006>apposé mon nom<E005> sur le\r\nregistre de l'établissement.");
                R(ref s, "All extremely easy to verify...<E049><E003 13><E025 1>and undeniable proof!", "C'est extrêmement aisé à vérifier...<E049><E003 13><E025 1>et c'est une preuve incontestable !");
                R(ref s, "Agh!<E049><E003 16> <E045>No!<E049><E003 14> <E025 3>I...", "Argh !<E049><E003 16> <E045>Non !<E049><E003 14> <E025 3>Je...");
                R(ref s, "There's no escape this time!", "Vous ne pouvez plus fuir !");
                R(ref s, "You can forget that you're a judge or a government\r\nminister.", "Oubliez votre statut de juge ou de ministre.");
                R(ref s, "It's time you gave the court an honest answer, <E049><E003 8><E025 3>as a\r\ncommon man.", "Il est temps de donner une réponse sincère au tribunal, <E049><E003 8><E025 3>en simple\r\ncitoyen.");
                R(ref s, "You killed Inspector Tobias Gregson and transported his\r\ncorpse back to Britain.", "Vous avez tué l'inspecteur Tobias Gregson et transporté son\r\ncadavre jusqu'en Grande-Bretagne.");
                R(ref s, "Then you dumped the body in the room on Fresno Street\r\nand made it look as if the murder had happened there.", "Puis vous avez déposé le corps dans la pièce de Fresno Street\r\npour faire croire que le meurtre s'y était déroulé.");
                R(ref s, "That's what really happened, <E049><E003 6><E025 3>isn't it...<E049><E003 18><E549 7 19 0 1><E046><E025 1>Seishiro Jigoku?!", "C'est bien ainsi que les choses se sont passées,<E049><E003 6><E025 3> n'est-ce pas...<E049><E003 18><E549 7 19 0 1><E046><E025 1>Seishiro Jigoku ?!");
                R(ref s, "It was that damned trial ten years ago...<E049><E003 15>\r\n<E042><CNTR><E025 3>That's when all this began.", "Tout est parti de ce maudit procès d'il y a dix ans...<E049><E003 15>\r\n<E042><CNTR><E025 3>C'est là que tout a commencé.");
                R(ref s, "Looking back now, <E049><E003 8><E357>my fate was decided that day.<E357><E003 20>\r\n<E042><CNTR><E025 4><E358>I was doomed <E091 3 105 6><E359>already.", "Avec le recul, <E049><E003 8><E357>mon sort s'est scellé ce jour-là.<E357><E003 20>\r\n<E042><CNTR><E025 4><E358>J'étais déjà <E091 3 105 6><E359>condamné.");
                R(ref s, "AAAAAAAAAAAA<E343>AAAAAAAA<E338>AAAAAAA<E343>AAAAAAAAA<E343>\r\n<E606>AAAAAAAAAA<E343>AAAAAAAAAAA<E046>AAAAAAAAAAAA<E343>RGH!", "AAAAAAAAAAAA<E343>AAAAAAAA<E338>AAAAAAA<E343>AAAAAAAAA<E343>\r\n<E606>AAAAAAAAAA<E343>AAAAAAAAAAA<E046>AAAAAAAAAAAA<E343>RGH !");
                R(ref s, "It's over!<E003 20>\r\n<E042><CNTR><E025 3>My life...<E003 20><E342>is over.", "C'est fini !<E003 20>\r\n<E042><CNTR><E025 3>Ma vie...<E003 20><E342>est anéantie.");
                return s;
            };

