            // [66] BB\script\output\_sce04_c302_0070_eng#8
            entryTranslators[@"BB\script\output\_sce04_c302_0070_eng#8"] = (s) => {
                R(ref s, "We've wasted enough time!", "Nous avons perdu assez de temps !");
                R(ref s, "It's clear to me <E049><E003 8><E025 2>that any further discussion of this case will\r\nbe fruitless.", "Il m'apparaît clairement <E049><E003 8><E025 2>que tout débat prolongé sur cette affaire sera\r\ninfructueux.");
                R(ref s, "Barok van Zieks, <E049><E003 8><E025 2>I would like to think that however\r\nmisguided...", "Drake Van Peers, <E049><E003 8><E025 2>j'ose croire que, si fourvoyé fussiez-vous...");
                R(ref s, "...you acted out of a sense of justice nonetheless.<E049><E003 12>\r\n<E025 3>Though it pains me to have reached this conclusion...", "... vous avez néanmoins agi selon votre sens de la justice.<E049><E003 12>\r\n<E025 3>Bien qu'il me soit douloureux d'en arriver là...");
                R(ref s, "Wait, My Lord!", "Attendez, Votre Honneur !");
                R(ref s, "In accordance with the findings of this court, <E049><E003 6><E025 3>I hereby\r\npronounce the defendant, <E049><E003 6><E025 3>Barok van Zieks...", "Conformément aux conclusions de ce tribunal, <E049><E003 6><E025 3>je déclare\r\npar la présente l'accusé, <E049><E003 6><E025 3>Drake Van Peers...");
                R(ref s, "That concludes business.<E049><E003 10>\r\n<E025 2>Court is adjourned!", "La séance est levée.<E049><E003 10>\r\n<E025 2>L'audience est terminée !");
                return s;
            };

            // [67] BB\script\output\_sce04_c303_0000_eng#2
            entryTranslators[@"BB\script\output\_sce04_c303_0000_eng#2"] = (s) => {
                R(ref s, "‘A British assassin to eliminate a professor in Japan.<E003 15>\r\n<E042><CNTR>A Japanese assassin to eliminate a detective in Britain.’", "« Un assassin britannique pour éliminer un professeur au Japon.<E003 15>\r\n<E042><CNTR>Un assassin japonais pour éliminer un détective en Grande-Bretagne. »");
                R(ref s, "‘Both assassins will use diplomatic immunity to evade\r\n<E042><CNTR>conviction and return safely to their homelands.’", "« Les deux assassins useront de l'immunité diplomatique pour échapper\r\n<E042><CNTR>à toute condamnation et regagner leur patrie sains et saufs. »");
                R(ref s, "The assassin exchange request arrived from Britain about\r\none year ago.", "La demande d'échange d'assassins est arrivée de Grande-Bretagne il y a\r\nenviron un an.");
                R(ref s, "...Though it was hardly a request.<E049><E003 10> <E025 3>It was <E006>a demand<E005>.", "... Bien que ce ne fût guère une demande.<E049><E003 10> <E025 3>C'était <E006>une exigence<E005>.");
                R(ref s, "And for that, <E049><E003 6>you decided to recruit Mr Asogi.", "Et pour cela, <E049><E003 6>vous avez décidé de recruter M. Asogi.");
                R(ref s, "But things didn't go according to plan.<E003 12>\r\nYour chosen assassin never made it to Britain.", "Mais les choses ne se sont pas déroulées comme prévu.<E003 12>\r\nL'assassin désigné n'est jamais parvenu en Grande-Bretagne.");
                R(ref s, "And you found yourself unable to dispatch a\r\nreplacement...", "Et vous vous êtes trouvé dans l'incapacité d'envoyer un remplaçant...");
                R(ref s, "...because I was already on my way to Britain at that time\r\nin Kazuma's place.", "... car j'étais déjà en route pour la Grande-Bretagne à ce moment-là\r\nà la place de Kazuma.");
                R(ref s, "And that <E049><E003 6><E145 47 70><E117 47 30><E003 15><E025 3><E239>left me with only one option for carrying out my\r\nobligation:", "Et cela <E049><E003 6><E145 47 70><E117 47 30><E003 15><E025 3><E239>ne m'a laissé qu'une seule option pour honorer mon\r\nengagement :");
                R(ref s, "To eliminate the mark myself.<E049><E003 10> Personally.", "Éliminer la cible moi-même.<E049><E003 10> En personne.");
                R(ref s, "Of course, <E049><E003 10><E025 2><E333>there was but a single opportunity for me to do\r\nthat.", "Bien sûr, <E049><E003 10><E025 2><E333>il n'y avait qu'une seule opportunité pour moi\r\nde le faire.");
                R(ref s, "The International Forensic Science Symposium,<E049><E003 5><E145 1 85><E118 1 0.9><E003 14> <E025 3>I\r\npresume?", "Le symposium international de médecine légale,<E049><E003 5><E145 1 85><E118 1 0.9><E003 14> <E025 3>je\r\nprésume ?");
                R(ref s, "That's right.", "C'est exact.");
                R(ref s, "I decided it would be safest to carry out the plan before\r\nmy arrival in Britain.", "J'ai jugé qu'il serait plus prudent d'exécuter le plan avant\r\nmon arrivée en Grande-Bretagne.");
                R(ref s, "So I enlisted the help of my British counterpart...", "J'ai donc fait appel à mon homologue britannique...");
                R(ref s, "...and made arrangements for a pretext that would take\r\nthe inspector to Dunkirk.", "... et fait en sorte de trouver un prétexte pour attirer\r\nl'inspecteur à Dunkerque.");
                R(ref s, "To lure the man in, <E049><E003 10><E025 3><E239>he was given a sham mission by the\r\nReaper.", "Pour l'appâter, <E049><E003 10><E025 3><E239>le Faucheur lui a confié une mission\r\nfeinte.");
                R(ref s, "W-<E049><E003 10><E025 2>What?!<E049><E003 12>\r\n<E025 3><E341><E007>(The Reaper...?)", "Q-<E049><E003 10><E025 2>Quoi ?!<E049><E003 12>\r\n<E025 3><E341><E007>(Le Faucheur... ?)");
                R(ref s, "But there's only one person who could have done that!", "Mais une seule personne pouvait faire cela !");
                R(ref s, "The mastermind of the entire operation:<E049><E003 15><E145 112 4><E118 112 1.15><E149 112 5 4><E003 20>\r\n<E238><E025 1><E006>the Reaper himself<E005>!", "Le commanditaire de toute cette opération :<E049><E003 15><E145 112 4><E118 112 1.15><E149 112 5 4><E003 20>\r\n<E238><E025 1><E006>le Faucheur en personne<E005> !");
                R(ref s, "So...<E003 12><E025 3>that means that the assassin exchange was...", "Alors...<E003 12><E025 3>cela signifie que l'échange d'assassins était...");
                R(ref s, "It was all planned by the Reaper!", "C'était l'œuvre du Faucheur depuis le début !");
                R(ref s, "I'm not at liberty to say anything about my British\r\ncounterpart.", "Je ne suis pas autorisé à divulguer quoi que ce soit sur mon\r\nhomologue britannique.");
                R(ref s, "Anyway, <E049><E003 8><E025 2>the inspector accepted the Reaper's mission and\r\ndutifully infiltrated my cabin on the steamship.", "Quoi qu'il en soit, <E049><E003 8><E025 2>l'inspecteur a accepté la mission du Faucheur et s'est\r\ndocilement infiltré dans ma cabine sur le paquebot.");
                R(ref s, "But it was all a trap designed to lead him to France...<E003 12>\r\n<E025 3>and his own death.", "Mais ce n'était qu'un piège destiné à le faire venir en France...<E003 12>\r\n<E025 3>pour y trouver la mort.");
                R(ref s, "Oh, <E049><E003 10><E341>how awful...", "Oh, <E049><E003 10><E341>quelle horreur...");
                R(ref s, "It was past nine o'clock when I returned to my cabin from\r\nthe dining hall that evening.", "Il était plus de neuf heures passées quand je suis rentré dans ma cabine\r\naprès le dîner ce soir-là.");
                R(ref s, "I didn't give him time to attack me.<E003 8> I choked him until he\r\nlost consciousness.", "Je ne lui ai pas laissé le temps de m'attaquer.<E003 8> Je l'ai étranglé\r\njusqu'à ce qu'il perde connaissance.");
                R(ref s, "But there was a guard just outside the door, <E049><E003 10><E145 47 70><E118 47 0.8><E003 8><E239>so I left it at\r\nthat for the time being.", "Mais un garde se tenait juste devant la porte, <E049><E003 10><E145 47 70><E118 47 0.8><E003 8><E239>alors j'en suis\r\nresté là pour le moment.");
                R(ref s, "Even the slightest noise might have aroused suspicion,<E049><E003 8> so\r\nI <E006>bided my time<E005>, <E049><E003 6>waiting...", "Le moindre bruit aurait pu éveiller les soupçons,<E049><E003 8> alors\r\nj'ai <E006>pris mon mal en patience<E005>, <E049><E003 6>en attendant...");
                R(ref s, "For <E006>the twenty minutes<E005> after ten o'clock...", "Pendant <E006>les vingt minutes<E005> après dix heures...");
                R(ref s, "I had intended to finish him by strangulation.<E049><E003 10>\r\n<E025 3>But moments before I had the chance...", "J'avais l'intention de l'achever en l'étranglant.<E049><E003 10>\r\n<E025 3>Mais quelques instants avant que j'en aie l'occasion...");
                R(ref s, "...he suddenly came round and <E341>went for me in a reckless\r\nmove.", "... il a subitement repris conscience et <E341>s'est jeté sur moi avec\r\ntémérité.");
                R(ref s, "*BANG!*", "*PAN !*");
                return s;
            };

            // [68] BB\script\output\_sce04_c303_0000_eng#3
            entryTranslators[@"BB\script\output\_sce04_c303_0000_eng#3"] = (s) => {
                R(ref s, "I'd received the British-issue gun sixteen years earlier,<E049><E003 8>\r\nbeing a member of the judiciary as a visiting student.", "J'avais reçu cette arme de dotation britannique seize ans plus tôt,<E049><E003 8>\r\nen tant que magistrat et étudiant étranger.");
                R(ref s, "...I never imagined I'd have to use it for something like\r\nthat.", "... Je n'aurais jamais pensé devoir m'en servir pour une chose pareille.");
                R(ref s, "So the revolver belongs to you, <E003 6><E145 61 5><E118 61 0.6><E025 3>does it?", "Ce revolver vous appartient donc, <E003 6><E145 61 5><E118 61 0.6><E025 3>n'est-ce pas ?");
                R(ref s, "Then the victim was killed inside your cabin on the\r\nSS Grouse.", "La victime a donc bien été tuée dans votre cabine à bord du\r\nSS Grouse.");
                R(ref s, "Which begs the question...", "Ce qui soulève la question...");
                R(ref s, "...of why you arranged for his body to be discovered in\r\nthe room on Fresno Street.", "... de savoir pourquoi vous avez fait en sorte que son corps soit découvert\r\ndans cette pièce de Fresno Street.");
                R(ref s, "...The young judicial assistant over there has already\r\nanswered that question.", "... La jeune assistante juridique a déjà apporté la réponse\r\nà cette question.");
                R(ref s, "There was no way I could take the body up on deck to\r\nthrow it over the side.", "Il m'était impossible de monter le corps sur le pont pour\r\nle passer par-dessus bord.");
                R(ref s, "That's precisely where all the crewmen were gathered\r\nfor the evacuation drill.", "C'est précisément là que tout l'équipage s'était rassemblé\r\npour l'exercice d'évacuation.");
                R(ref s, "So before the first-class cabin sentries returned,<E049><E003 8> I took\r\nthe corpse to the refrigeration room.", "Alors, avant que les sentinelles de première classe ne reviennent,<E049><E003 8> j'ai\r\ntransporté la dépouille dans la chambre froide.");
                R(ref s, "And then on arriving in Dover, <E049><E003 6>you concealed the body in\r\nyour trunk in order to smuggle it past the border police.", "Et ensuite, à l'arrivée à Douvres, <E049><E003 6>vous avez dissimulé le corps dans\r\nvotre malle pour le faire passer sous le nez de la police des frontières.");
                R(ref s, "I knew I needed to take steps <E049><E003 6><E025 2>if the police were to be\r\nconvinced when the body was found in London.", "Je savais que je devais prendre des mesures <E049><E003 6><E025 2>pour donner le change\r\nà la police lorsque le corps serait découvert à Londres.");
                R(ref s, "In that case...<E049><E003 12><E025 2>you must have known.", "Dans ce cas...<E049><E003 12><E025 2>vous deviez le savoir.");
                R(ref s, "You must have had intimate details <E049><E003 6><E025 3><E238>of Inspector Gregson's\r\nintended <E006>schedule<E005>.", "Vous deviez connaître les moindres détails <E049><E003 6><E025 3><E238>de <E006>l'emploi du temps<E005>\r\nprévu pour l'inspecteur Gregson.");
                R(ref s, "Yes.<E049><E003 10> <E025 2>My British counterpart sent me everything I needed\r\nto know.", "Oui.<E049><E003 10> <E025 2>Mon homologue britannique m'a transmis toutes les indications\r\nnécessaires.");
                R(ref s, "The inspector was due at Fresno Street at five o'clock\r\nthat afternoon.", "L'inspecteur devait se rendre sur Fresno Street à cinq heures\r\nde l'après-midi.");
                R(ref s, "In order to meet a man by the name of Hugh Boone, <E049><E003 8><E025 2>from\r\nwhom he would take back his police identification.", "Afin d'y retrouver un certain Hugh Boone, <E049><E003 8><E025 2>qui devait lui restituer\r\nses papiers de police.");
                R(ref s, "I decided that man would be the perfect person to set up\r\nas the culprit.", "J'ai jugé que cet homme ferait le coupable idéal à faire accuser.");
                R(ref s, "So I took a hackney carriage over there with the body\r\nstill in my trunk.", "J'ai donc pris un fiacre pour m'y rendre avec le corps toujours\r\ndans ma malle.");
                R(ref s, "That must have been just after we took this photograph\r\nwith you at the hotel, then...", "Ce devait être juste après cette photographie prise avec vous\r\nà l'hôtel, alors...");
                return s;
            };

            // [69] BB\script\output\_sce04_c303_0000_eng#4
            entryTranslators[@"BB\script\output\_sce04_c303_0000_eng#4"] = (s) => {
                R(ref s, "Yes, <E003 8><E025 2>I wasn't expecting a welcoming committee.<E003 10>\r\n<E025 3>I was more than a little nervous.", "Oui, <E003 8><E025 2>je ne m'attendais pas à un comité d'accueil.<E003 10>\r\n<E025 3>J'étais pour le moins nerveux.");
                R(ref s, "On Fresno Street, <E049><E003 6>I spotted a young girl selling little\r\nfirecrackers.", "Sur Fresno Street, <E049><E003 6>j'ai aperçu une fillette vendant des petits\r\npétards.");
                R(ref s, "(Miss Venus <E003 6>of course...)", "(Mademoiselle Vénus, <E003 6>bien sûr...)");
                R(ref s, "I conceived of the candle trick there and then.", "C'est là que j'ai imaginé le stratagème de la bougie.");
                R(ref s, "So I donned a simple disguise and approached the girl to\r\nbuy enough firecrackers to replicate a gunshot.", "J'ai donc endossé un déguisement sommaire et approché la gamine pour\r\nacheter assez de pétards pour imiter une détonation.");
                R(ref s, "What sort of disguise?", "Quel genre de déguisement ?");
                R(ref s, "For some reason, <E049><E003 6><E025 2>the inspector had a bright red hairpiece\r\nin his own travelling case.", "Pour une raison inconnue, <E049><E003 6><E025 2>l'inspecteur avait un postiche roux flamboyant\r\ndans ses affaires de voyage.");
                R(ref s, "So I put that on.<E049><E003 8> <E145 47 77><E118 47 1.25><E003 10><E239><E025 2>Although I suspect I drew more attention\r\nto myself in that than I would have otherwise.", "Je l'ai donc coiffé.<E049><E003 8> <E145 47 77><E118 47 1.25><E003 10><E239><E025 2>Même si je crains d'avoir ainsi attiré\r\nplus l'attention que je ne l'aurais fait autrement.");
                R(ref s, "The hairpiece we found at the scene.<E049><E003 10> <E060 0 119 0 0>The inspector had\r\nit ready for the Red-Headed League investigation.", "Le postiche retrouvé sur les lieux.<E049><E003 10> <E060 0 119 0 0>L'inspecteur l'avait préparé\r\npour l'enquête de la Ligue des Rouquins.");
                R(ref s, "I only arrived at the room at around quarter to five.", "Je ne suis arrivé dans la pièce que vers cinq heures moins le quart.");
                R(ref s, "So I quickly placed the body on the floor, <E049><E003 8>moved the\r\nnoticeboard <E049><E003 10>and set up my little candle trick.", "J'ai donc rapidement déposé le corps, <E049><E003 8>déplacé le tableau d'affichage<E049><E003 10>\r\net installé mon petit tour avec la bougie.");
                R(ref s, "I arranged it so the firecrackers would go off with a bang\r\naround fifteen minutes later.", "J'ai fait en sorte que les pétards explosent dans une détonation\r\nenviron quinze minutes plus tard.");
                R(ref s, "So that Mr Boone, <E049><E003 8>who was due to arrive at five, <E049><E003 6>would\r\nwalk straight into a trap?", "Pour que M. Boone, <E049><E003 8>qui devait arriver à cinq heures, <E049><E003 6>tombe\r\ndroit dans le piège ?");
                R(ref s, "Except...<E003 12>at the last moment, <E049><E003 8><E145 47 84><E118 47 0.8><E003 15><E239>I made a careless blunder.", "Sauf que...<E003 12>au dernier moment, <E049><E003 8><E145 47 84><E118 47 0.8><E003 15><E239>j'ai commis une fâcheuse bévue.");
                R(ref s, "What was that?", "Laquelle ?");
                R(ref s, "I imagine...<E049><E003 10><E164 9 83 1 2 7 0 0 1><E139 9><E025 2>it was the bag of <E006>fish and chips<E005>.", "J'imagine...<E049><E003 10><E164 9 83 1 2 7 0 0 1><E139 9><E025 2>qu'il s'agissait du paquet de <E006>poisson-frites<E005>.");
                R(ref s, "I didn't notice that it had fallen out of his overcoat pocket\r\nwhen I moved the body to the refrigeration room.", "Je n'avais pas remarqué qu'il était tombé de sa poche de pardessus\r\nquand j'ai déplacé le corps dans la chambre froide.");
                R(ref s, "I put it back into his pocket the following morning, <E049><E003 8><E025 3>but...", "Je l'ai remis dans sa poche le lendemain matin, <E049><E003 8><E025 3>mais...");
                R(ref s, "Well, <E049><E003 12>it seems the warmth of the heated cabin had\r\naccelerated the decay of the fish.", "Eh bien, <E049><E003 12>la chaleur de la cabine chauffée avait manifestement\r\naccéléré la décomposition du poisson.");
                R(ref s, "Anyway, <E049><E003 8>that's...", "Bref, <E049><E003 8>c'est...");
                R(ref s, "That's everything.<E049><E003 12> <E025 3>All the sordid details of what I did.", "C'est tout.<E049><E003 12> <E025 3>Tous les sordides détails de mes actes.");
                return s;
            };

            // [70] BB\script\output\_sce04_c303_0000_eng#5
            entryTranslators[@"BB\script\output\_sce04_c303_0000_eng#5"] = (s) => {
                R(ref s, "I've heard enough.", "J'en ai assez entendu.");
                R(ref s, "We've arrived at the truth <E049><E003 8><E145 61 7><E118 61 0.7><E025 3>about the murder of one of the\r\ncountry's most capable and respected police inspectors.", "Nous avons établi la vérité <E049><E003 8><E145 61 7><E118 61 0.7><E025 3>sur le meurtre de l'un des\r\ninspecteurs les plus compétents et respectés de ce pays.");
                R(ref s, "The witness will be tried in the coming days.", "Le témoin sera jugé dans les prochains jours.");
                R(ref s, "For a crime of such a vile nature...<E049><E003 20><E145 61 7><E118 61 0.55><E025 3>you can expect the\r\nmost severe penalty.", "Pour un forfait d'une telle ignominie...<E049><E003 20><E145 61 7><E118 61 0.55><E025 3>vous devez vous attendre\r\nà la sanction la plus sévère.");
                R(ref s, "An exchange of assassins...<E049><E003 15>\r\n<E341><E025 3>What a foolhardy idea...", "Un échange d'assassins...<E049><E003 15>\r\n<E341><E025 3>Quelle idée insensée...");
                R(ref s, "Mr Jigoku!<E049><E003 14>\r\n<E335>One last detail!", "Monsieur Jigoku !<E049><E003 14>\r\n<E335>Un dernier détail !");
                R(ref s, "Who was your counterpart in Britain?<E049><E003 14> <E025 1><E046>Who was the\r\nmastermind behind the assassin exchange?", "Qui était votre complice en Grande-Bretagne ?<E049><E003 14> <E025 1><E046>Qui a orchestré\r\ncet échange d'assassins ?");
                R(ref s, "Nothing you say now can make matters any worse for\r\nyou!<E049><E003 15> <E164 1 8 1 2 8 0 1 1><E139 1><E025 1>Just tell us!", "Rien de ce que vous direz ne pourra aggraver votre cas !<E049><E003 15>\r\n<E164 1 8 1 2 8 0 1 1><E139 1><E025 1>Dites-le-nous !");
                R(ref s, "Eeeeeenough!", "Caaaaa suffit !");
                R(ref s, "I've already told you...<E003 15><E025 1><E332>that I cannot say!", "Je vous l'ai déjà dit...<E003 15><E025 1><E332>je ne peux rien dire !");
                R(ref s, "Even though as things stand, <E049><E003 10><E025 2><E330>you may very well never\r\nset foot in your homeland again?", "Même si, dans ces conditions, <E049><E003 10><E025 2><E330>vous risquez fort de ne jamais\r\nreposer le pied sur votre terre natale ?");
                R(ref s, "What are you waiting for?<E049><E003 15>\r\n<E025 1><E045>Can't we get this over with now?!", "Qu'attendez-vous donc ?<E049><E003 15>\r\n<E025 1><E045>En finissons-en une bonne fois pour toutes !");
                R(ref s, "It's finished...<E003 15><E025 1><E338><E341>all of it!", "C'est fini...<E003 15><E025 1><E338><E341>tout est fini !");
                R(ref s, "...I'm finished...", "... Je suis perdu...");
                R(ref s, "Then, <E049><E003 12><E025 2>in the name of Her Majesty the Queen, <E049><E003 8>I now\r\npronounce the findings of this court.", "Dès lors, <E049><E003 12><E025 2>au nom de Sa Majesté la Reine, <E049><E003 8>je prononce\r\nles conclusions de ce tribunal.");
                R(ref s, "This man before us has admitted <E049><E003 12><E025 1><E121 23 25 0 0><E130 15 1><E046><E339>to the wilful murder of\r\nTobias Gregson.", "L'homme devant nous a confessé <E049><E003 12><E025 1><E121 23 25 0 0><E130 15 1><E046><E339>l'homicide volontaire de\r\nTobias Gregson.");
                R(ref s, "Seishiro Jigoku, <E049><E003 15><E145 61 7><E118 61 0.7><E025 2>it is the opinion of this court that you\r\nshould be found...", "Seishiro Jigoku, <E049><E003 15><E145 61 7><E118 61 0.7><E025 2>ce tribunal estime que vous devez\r\nêtre reconnu...");
                R(ref s, "And may I remind all those present <E049><E003 10><E025 1><E346>of the strict\r\nconfidentiality demanded by this closed court!", "Et je rappelle à toutes les personnes présentes <E049><E003 10><E025 1><E346>la stricte\r\nconfidentialité qu'exige ce procès à huis clos !");
                return s;
            };

        }
    }
